import React from 'react';
import { DropdownMenu } from '@gravity-ui/uikit';
import type { ButtonView } from '@gravity-ui/uikit';

const actions = [
  { text: 'Редактировать', action: () => alert('Редактировать'), href: undefined as unknown as never },
  { text: 'Копировать', action: () => alert('Копировать'), href: undefined as unknown as never },
  { text: 'Переместить', action: () => alert('Переместить'), href: undefined as unknown as never },
  { text: 'Архивировать', action: () => alert('Архивировать'), href: undefined as unknown as never },
  { text: 'Удалить', action: () => alert('Удалить'), href: undefined as unknown as never },
];

export function App() {
  return (
    <div style={{ padding: 24 }}>
      <DropdownMenu
        items={[
          actions.slice(0, 2) as any,
          actions.slice(2) as any,
        ]}
        defaultSwitcherProps={{ view: 'action' as ButtonView, children: 'Действия' }}
      />
    </div>
  );
}
TSXEOF"

